fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            if n < 4 {
                // If n is less than 4, we need to add enough items to reach 4.
                4 - n
            } else {
                // If n is already at least 4, we only need to add 1 if it's odd, 0 if it's even.
                n & 1
            }
        })
        .collect()
}

