        assert_eq!(solve(vec![3]), vec![1]);
        assert_eq!(solve(vec![4]), vec![0]);
        assert_eq!(solve(vec![5]), vec![1]);
        assert_eq!(solve(vec![10]), vec![0]);
        assert_eq!(solve(vec![11, 12, 13, 2, 3]), vec![1, 0, 1, 2, 1]);
